const title:(p:Phase,z:boolean)=>string=(p,z)=>({site:z?'選擇基地位置':'Choose a base site',event:z?'回應太空天氣背景':'Respond to event context',evidence:z?'檢查觀測證據':'Examine observation evidence',repair:z?'連接維修線路':'Connect the repair circuit',finale:z?'整合基地優先工作':'Set outpost priorities'})[p];
const copy:(p:Phase,z:boolean)=>string=(p,z)=>({site:z?'看看三個候選地點，找比較平坦的一格。拖動基地模型，再決定要住在哪裡。':'Look at the three candidate sites. Find a flatter place, move the habitat token, and choose where to build.',event:z?'先看事件日期和類型，再轉動天線。選擇保留備援或繼續傳送。':'Notice the event date and type, then turn the antenna. Choose whether to save backup or keep sending.',evidence:z?'你真的看見了什麼？影像有陰影，但陰影本身不能證明有水冰。':'What can you actually see? The image shows a shadow, but a shadow alone cannot prove water ice.',repair:z?'先找出電力路徑，再把備援插頭接到生命維持接口。':'Trace the power path, then connect backup power to life support.',finale:z?'選出至少兩項優先工作，看看能源、水和通訊如何改變。':'Choose at least two priorities and see how power, water and communications change.'})[p];
