 private pointerDown(e:PointerEvent){if(!this.open||this.root.dataset.sourcesOpen==='true'||e.button!==0)return;const rect=this.canvas.getBoundingClientRect();this.ndc.set(((e.clientX-rect.left)/rect.width)*2-1,-((e.clientY-rect.top)/rect.height)*2+1);this.raycaster.setFromCamera(this.ndc,this.camera);const hits=this.raycaster.intersectObjects(this.interactive,true);if(!hits.length)return;e.preventDefault();e.stopPropagation();const object=hits[0].object;let node:THREE.Object3D|null=object;while(node&&!node.userData.kind)node=node.parent;if(!node)return;const kind=node.userData.kind as string;this.lastPointerDownKind=kind;if(kind==='base'){this.drag={id:e.pointerId,kind:'base',startX:e.clientX,startY:e.clientY};this.parallaxPaused=true;}else if(kind==='antenna'){this.drag={id:e.pointerId,kind:'antenna',startX:e.clientX,startY:e.clientY};this.parallaxPaused=true;}else if(kind==='solar-module'&&!this.state.solarInstalled){this.drag={id:e.pointerId,kind:'solar-module',startX:e.clientX,startY:e.clientY};this.parallaxPaused=true;}else if(kind==='site'){this.selectSite(Number(node.userData.index));}else if(kind==='source'){this.openSource(Number(node.userData.index));}else if(kind==='screen'){this.focusScreen();}else if(kind==='classification'){this.classify(node.userData.value as BoardState['evidence']);}else if(kind==='port'){this.connectPort(Number(node.userData.index));}try{this.canvas.setPointerCapture(e.pointerId);}catch{/* raycast targets remain large for tap fallback */}}
