 private updateCable(){const p=this.state.repairLinked?[-1.15,-.2]:this.selectedPort===0?[-1.15,-.68]:[-1.15,.25];const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(p[0],.26,.25),new THREE.Vector3((p[0]+p[1])/2,.45,.25),new THREE.Vector3(p[1],.26,.25)]);const old=this.cable.geometry;this.cable.geometry=new THREE.TubeGeometry(curve,24,.027,8,false);old.dispose();}
 pointFor(kind:'base'|'site'|'source'|'antenna'|'classification'|'port'|'screen'|'solar-module'|'solar-socket',index=0){this.scene.updateMatrixWorld(true);this.camera.updateMatrixWorld();let object:THREE.Object3D|undefined;if(kind==='base')object=this.physical.getObjectByName('draggable-habitat-token');else if(kind==='antenna')object=this.antenna.children[2];else if(kind==='screen')object=this.screenFrame;else if(kind==='solar-module')object=this.solarPanel.children[0];else if(kind==='solar-socket')object=this.solarSocket;else object=this.interactive.find(item=>item.userData.kind===kind&&Number(item.userData.index??0)===index);if(kind==='site')object=this.siteMeshes.find(item=>Number(item.userData.index)===index&&item.userData.kind==='site');if(kind==='classification')object=this.interactive.find(item=>item.userData.kind===kind&&item.userData.value===(['observe','infer','unknown'][index]));if(!object)return{x:0,y:0};const p=object.getWorldPosition(new THREE.Vector3()).project(this.camera);const rect=this.canvas.getBoundingClientRect();return{x:rect.left+(p.x+1)*rect.width/2,y:rect.top+(1-p.y)*rect.height/2};}
 hitKindAt(x:number,y:number){const rect=this.canvas.getBoundingClientRect();this.ndc.set((x-rect.left)/rect.width*2-1,-((y-rect.top)/rect.height)*2+1);this.raycaster.setFromCamera(this.ndc,this.camera);const hit=this.raycaster.intersectObjects(this.interactive,true)[0]?.object;let node:THREE.Object3D|null=hit??null;while(node&&!node.userData.kind)node=node.parent;return node?.userData.kind??null;}
