 private sourceSummary(id:string,z:boolean){const labels:Record<string,[string,string]>={lola:['先看哪個候選地點比較平，再找它的位置線索。','Compare which candidate looks flatter, then find its location clue.'],donki:['事件日期和名稱告訴我們發生了什麼；它不是危險分數。','The date and name tell us what happened; they are not a danger score.'],'images-api':['先說出影像裡看得見的特徵，再想想還缺什麼證據。','Name what you can see in the image, then consider what evidence is missing.'],bvad:['這份生活用水參考幫助我們討論基地如何分配資源。','This water-use reference helps us discuss how a habitat shares resources.'],moonbase:['基地系統彼此相連，選擇一項工作也可能影響另一項。','Outpost systems connect, so one choice can affect another.']};return(labels[id]??labels.moonbase)[z?0:1];}
 private clueChoices(id:string,z:boolean):[string,string]{const choices:Record<string,[string,string][]>={lola:[['地點與地形位置','事件發生日期'],['Location and terrain position','Event date']],donki:[['事件日期和類型','基地地面的坡度'],['Event date and type','The slope of the base terrain']], 'images-api':[['影像日期與拍攝中心','直接測量到水冰'],['Image date and imaging center','A direct measurement of water ice']],bvad:[['每人每天的用水參考','天線訊號方向'],['Daily water-use reference per person','Antenna signal direction']],moonbase:[['基地系統如何互相影響','即時任務指令'],['How outpost systems affect one another','A real-time mission command']]};return choices[id]?.[z?0:1]??choices.moonbase[z?0:1];}
 private clueQuestion(id:string,z:boolean){const labels:Record<string,[string,string]>={lola:['哪個線索能幫我們比較基地位置？','Which clue helps compare base locations?'],donki:['哪個線索告訴我們事件發生了什麼時候？','Which clue tells us when the event happened?'],'images-api':['哪個線索幫我們辨認這張影像？','Which clue helps identify this image?'],bvad:['哪個線索和基地用水有關？','Which clue is about the outpost’s water use?'],moonbase:['哪個線索能幫我們理解基地系統？','Which clue helps explain outpost systems?']};return(labels[id]??labels.moonbase)[z?0:1];}
 private answerClue(id:string,choice:number,item:SourceCard){const z=this.language==='zh',correct=choice===0;this.state.sourceAttempts??={};if(correct){if(!this.state.sourceClues.includes(id))this.state.sourceClues.push(id);this.tutorial('source');if(this.state.solarInstalled)this.state.tutorialStep=Math.max(this.state.tutorialStep,3);this.message=z?'線索找到了！它能幫我們回答任務問題。這些資源變化仍是教育模型。':'Clue found. It helps answer the mission question; resource effects are still educational models.';}else{const attempts=(this.state.sourceAttempts[id]??0)+1;this.state.sourceAttempts[id]=attempts;const subject=z?({lola:'位置與地形',donki:'事件日期和類型','images-api':'影像日期與拍攝中心',bvad:'每日用水量',moonbase:'基地系統'}[id]??'任務線索'):({lola:'location and terrain',donki:'event date and type','images-api':'image date and center',bvad:'daily water use',moonbase:'outpost systems'}[id]??'mission clue');this.message=attempts===1?(z?'再看看任務問題，想想時間、地點或資源哪一項最有關。':'Look at the mission question again. Is time, location or a resource most relevant?'):(z?`提示：這題要找「${subject}」線索。`:`Hint: find the “${subject}” clue.`);}this.save();this.render();this.showSources(true,item);this.root.querySelector<HTMLButtonElement>(correct?'.source-close':'.source-choice')?.focus();}
 private sourceClue(id:string,z:boolean){if(id==='lola'){const site=this.sites().find(item=>item.id===this.state.site);return site?`${z?'位置':'Location'} ${site.latitude.toFixed(4)}°, ${site.longitude.toFixed(4)}° · ${z?'相對地形':'Relative topography'} ${site.topographyRelativeToMeanRadius} m · ${z?'衍生坡度':'Derived slope'} ${site.slope.toFixed(2)}°*`:z?'先選一個候選點，再查看座標與坡度。':'Choose a candidate to inspect its coordinates and derived slope.';}if(id==='donki'){const e=this.event();return e?`${e.eventType??'NASA event'} · ${e.observedAt??e.retrievedAt??''} · ${e.id}`:this.eventDisplay();}if(id==='images-api'){const image=getStoredNASAImages()[0];return image?`${image.nasaId} · ${image.dateCreated} · ${image.center}`:(z?'目前沒有可用 API 項目。':'No stored API item is available.');}if(id==='bvad')return z?'BVAD Rev. 2 · 表 4-20 · 印刷頁 72 · 3.2 kg／人／日（Transit Vehicle 情境）。':'BVAD Rev. 2 · Table 4-20 · printed p.72 · 3.2 kg/person-day (Transit Vehicle scenario).';return z?'NASA 月球基地系統背景；此遊戲的狀態改變是教育模型。':'NASA lunar-base systems context; game state changes are educational models.';}
