 private tutorial(step:'drag'|'source'|'assembly'|'antenna'){if(this.state.tutorialDone)return;const progress={drag:1,source:2,assembly:3,antenna:4}[step];this.state.tutorialStep=Math.max(this.state.tutorialStep,progress);this.root.dataset.tutorialStep=String(this.state.tutorialStep);this.save();}
