 hide(_showDock=true){this.open=false;this.cameraMode='overview';this.parallaxTarget.set(0,0);this.physical.rotation.set(-.13,0,0);this.physical.visible=false;this.root.hidden=true;this.onVisibility(false);document.body.classList.remove('board-mode');this.root.dataset.sourcesOpen='false';}
