 private complete(phase:Phase,choice:string,result:string,values:Record<string,unknown>){if(!this.applyDecision(phase,values)){this.message=this.language==='zh'?'資源不足，請調整選擇後重試。':'Not enough resources. Adjust the choice and retry.';this.render();return false;}this.syncResources();this.state.completed.push(phase);const source=phaseSource[phase];this.state.records.push({phase,choice,result,source:source.id,at:new Date().toISOString()});this.state.phase=Math.min(5,this.state.phase+1);if(this.state.tutorialStep>=4){this.state.tutorialStep=5;this.state.tutorialDone=true;}const explanations:Record<Phase,[string,string]>={site:['地形比較提供一項規劃線索，太陽能板則讓基地能收集陽光；這些都不會單獨保證基地安全。','Terrain comparison offers one planning clue, and the solar array collects sunlight; neither guarantees base safety.'],event:['保留備援或繼續傳送會改變遊戲資源；這不是太空天氣危險預測。','Saving backup or continuing transmission changes game resources; this is not a space-weather hazard forecast.'],evidence:['把陰影判斷為推論很重要：影像線索不等於水冰測量。','Calling a shadow claim an inference matters: an image clue is not an ice measurement.'],repair:['接通備援電力後，遊戲中的生命維持資源會更新；維修成本是教育規則。','Connecting backup power updates simulated life-support resources; repair costs are educational rules.'],finale:['你選的優先工作已影響結算；這是用來練習取捨的教育模型。','Your priorities affect the result; this is an educational model for practicing trade-offs.']};this.message=explanations[phase][this.language==='zh'?0:1];this.save();this.onChanged();this.render();return true;}
 private sites(){return getLunarSiteCandidates().records.slice(0,3);}
